D026 ;SPRITE MUTICOLOR 1SP0COL = $D027 ;SPRITE COLOR 0SP1COL = $D028 ;SPRITE COLOR 1SP2COL = $D029 ;SPRITE COLOR 2SP3COL = $D02A ;SPRITE COLOR 3SP4COL = $D02B ;SPRITE COLOR 4SP5COL = $D02C ;SPRITE COLOR 5SP6COL = $D02D ;SPRITE COLOR 6SP7COL = $D02E ;SPRITE COLOR 7SIDREG = $D400 ;SID REGISTERSFRELO1 = $D400 ;SID VOC 1FREHI1 = $D401 ;DIS VOC 1PWLO1  = $D402 ;PW VOC 1PWHI1  = $D403 ;PW VOC 1VCREG1 = $D404 ;VOC 1 REGATDCY1 = $D405 ;ADR VOC 1SUREL1 = $D406 ;SR VOC 1FRELO2 = $D407 ;SID VOC 2FREHI2 = $D408 ;DIS VOC 2PWLO2  = $D409 ;PW VOC 2PWHI2  = $D40A ;PW VOC 2VCREG2 = $D40B ;VOC 2 REGATDCY2 = $D40C ;ADR VOC 2SUREL2 = $D40D ;SR VOC 2FRELO3 = $D40E ;SID VOC 3FREHI3 = $D40F ;DIS VOC 3PWLO3  = $D410 ;PW VOC 3PWHI3  = $D411 ;PW VOC 3VCREG3 = $D412 ;VOC 3 REGATDCY3 = $D413 ;ADR VOC 3SUREL3 = $D414 ;SR VOC 3CUTLO  = $D415 ;CUT OFF FILTERCUTHI  = $D416 ;CUT OFF FILTERRESON  = $D417 ;RESONANCESIGVOL = $D418 ;VOLUME AND FILTERPOTX   = $D419 ;GAME PADDLEPOTY   = $D41A ;GAME PADDLERANDOM = $D41B ;ENV3   = $D41C ;COLRAM = $D800 ;CIAPRA = $DC00 ;PORT A REGCIAPRB = $DC01 ;PORT B REGCIDDRA = $DC02 ;DATA A REGCIDDRB = $DC03 ;DATA B REGTIMALO = $DC04 ;TIMER ATIMAHI = $DC05 ;TIMER ATIMBLO = $DC06 ;TIMER BTIMBHI = $DC07 ;TIMER BCIAICR = $DC0D ;IRQ CNTRL REGCIACRA = $DC0E ;CNTRL REG ACIACRB = $DC0F ;CNTRL REG B;********************************; SPRITE DEFINITION;********************************;XXFC00 SPRITE  1 = LANDER;XXFC40 SPRITES 2 = EXPLOSION 1;XXFC80 SPRITES 3 = EXPLOSION 2;XXFCC0 SPRITES 4 = EXPLOSION 3;XXFD00 SPRITES 5 = EXPLOSION 4;XXFD40 SPRITES 6 = EXPLOSION 5;XXFD80 SPRITES 7 = EXPLOSION 6;XXFDC0 SPRITES 8 = EXPLOSION 7;XXFE00 SPRITE  9 = MAIN ENGINE 1;XXFE40 SPRITE 10 = MAIN ENGINE 2;XXFE80 SPRITE 11 = LEFT THRUSTER;XXFEC0 SPRITE 12 = RIGHT THRUSTER;********************************; HARDWARE VECTORS;********************************;NMIVEC = $FFFA;RESVEC = $FFFC;IRQVEC = $FFFE;********************************; SETUP INITIAL VALUES FOR VIC-II; REGISTERS $D011-$D02E;********************************XXE000 .BYTE $1B       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $08       .BYTE $00       .BYTE $1E       .BYTE $FF       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $02       .BYTE $06       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $03       .BYTE $02       .BYTE $08       .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $00;********************************; SETUP INITIAL VALUES FOR VIC-II; REGISTERS $D400-$D418;********************************XXE01E .BYTE $00       .BYTE $00       .BYTE $00       .BYTE $08       .BYTE $40       .BYTE $00       .BYTE $D0       .BYTE $FF       .BYTE $80       .BYTE $00       .BYTE $00       .BYTE $80       .BYTE $80       .BYTE $78       .BYTE $00       .BYTE $09       .BYTE $00       .BYTE $00       .BYTE $80       .BYTE $00       .BYTE $FB       .BYTE $FF       .BYTE $34       .BYTE $04       .BYTE $10;********************************; NMI/RESET ENTRY POINT;********************************XXNMIV LDX #$FA       TXS        CLD        SEI ;********************************; SETUP INITIAL VALUES FOR VIC-II; REGISTERS $D011-$D02E;********************************       LDX #$1DXXE03E LDA XXE000,X       STA SCROLY,X       DEX        BPL XXE03E;********************************; SETUP INITIAL VALUES FOR SID; REGISTERS $D400-$D418;********************************       LDX #$18XXE049 LDA XXE01E,X       STA SIDREG,X       DEX        BPL XXE049;********************************; SETUP INITIAL VALUES FOR CIA; REGISTERS ;********************************       LDA #$7F   ;MASK BITS       STA CIAICR ;DISBALE IRQ       LDA #$08       STA CIACRB       LDX #$00       STX CIDDRB       DEX        STX CIDDRA       LDA #$05       STA $01       LDA #$2F      ;'/'       STA $00       LDA #$1B       STA TIMALO       LDA #$41      ;'A'       STA TIMAHI       LDA #$81      ;ENABLE TIMER A       STA CIAICR    ;SET IRA        LDA #$11      ;START TIMER 1       STA CIACRA    ;SET IRQ;	          LDA #$00       STA $1A       STA $1B       STA $2B;       LDA #$14      ;VERTICAL VELOCITY       STA $2E       JSR XXED7C;********************************; DISPLAY INSTRUCTION SCREEN	   ;********************************XXE090 JMP XXE7A0;********************************; RETURN FROM LOOP WAITING ON; PRESS <F1> TO START;********************************XXE093 SEI        LDA #$00       STA $22       LDA #$00       STA VCREG1       STA VCREG2       STA VCREG3	;          LDA #$1F       STA SIGVOL	;          JSR XXED7C       LDA #$00       STA BGCOL0       STA EXTCOL       LDA #$00       STA $2B       LDA #$FF       STA $12       STA $13    ;FUEL QTY FULL       LDA #$00       STA $15       STA $18       STA $19       STA $21    ;FUEL STATUS 0=HAVE FUEL;	          JSR XXEE5A ;SET DISPLAY SCORE 0       LDA #$01       STA $20XXE0CE LDX $15       CPX #$10       BEQ XXE0D5       INX XXE0D5 STX $15;********************************; RUN SIMULATED GAME CYCLE`;********************************       LDA ZZE0DE-1,X       STA $14        ;VERTICAL VELOCITY       BNE XXE0EE;********************************; SEED FOR INITIAL CONDITIONS OF; LANDER VERTICAL VELOCITY;********************************ZZE0DE .BYTE $04 ;$04       .BYTE $05 ;$05       .BYTE $04 ;$04       .BYTE $05 ;$05       .BYTE $06 ;$06       .BYTE $05 ;$05       .BYTE $06 ;$06       .BYTE $06 ;$06       .BYTE $06 ;$06       .BYTE $07 ;$07       .BYTE $08 ;$08       .BYTE $07 ;$07       .BYTE $07       .BYTE $08       .BYTE $09       .BYTE $09;********************************; ENTRY POINT FOR START GAME CYCLE;********************************XXE0EE LDA #$FF       STA $1C       LDA #$50      ;'P'       LDX #$00       STX $08       STA $09       STX $0A       LDA #$6A       STX $0D       STA $0E;       STX $0F       LDA #$00          STA    $10       STA $11       STA $0C       LDA #$FF       STA $0B       JSR XXEBD6 ;DRAW FUEL GAUGE       LDA #$00       STA $16    ;ZERO FIRE BUTTON OR F1       STA $17    ;ZERO KEY A OR D        LDA #$03       STA SP1COL       JSR XXE173       LDX #$03       JSR DELAY1       LDA $D01F;********************************	   ; PLAY TUNE 1 START OF PLAY   ;******************************** .IFN TUNE1 <       JSR XXE29A .ELSE	   	   NOP	   NOP	   NOP.ENDIF;********************************;;********************************	   XXE12C LDA $25       CMP #$32      ;'2'       BCS XXE144       LDA $24       BEQ XXE13E;	          LDA SPX       ;WHERE ARE WE       CMP #$18      ;IF HERE       BCS XXE144    ;MAKE A DECISION       BCC XXE14E;	   XXE13E LDA SPX       CMP #$18       BCS XXE14E;	   XXE144 LDA $D01F    ;SPBGCL COLLISON REG       AND #$02     ;DID SPRITE 2 COLLIDE       BEQ XXE14E   ;MAKE A DECISION       JMP XXE44B;********************************XXE14E JSR XXE173       LDA $1E       BEQ XXE158       JMP XXE55C;********************************XXE158 JSR XXE2C8       JSR XXEBD6    ;DRAW FUEL GAUGE       LDA $0F       BNE XXE16B       LDA $0E       CMP #$3A      ;':'       BCS XXE16B       JMP XXE50C;********************************XXE16B LDX #$03       JSR DELAY1       JMP XXE12C;********************************XXE173 JSR XXE1C4       CPY $1C       BEQ XXE188       STY $1C; DISABLE ALL SRPITES	          LDA #$00       STA SPENA;	          JSR XXEC72       LDA #$00       STA $21 ;FUEL STATUSXXE188 LDX $1C       BNE XXE1A1       LDA $0A       LSR A       STA $24       LDA $09       ROR A       STA SPX       LDA $0F       LSR A       LDA $0E       ROR A       STA $25       JMP XXE38D;********************************XXE1A1 LDA $09       SEC        ;SBC XXE1BA,X       SBC ZZE1BB-1,X       STA SPX       LDA $0A       SBC XXE1BD,X       STA $24       LDA $0E       SEC        SBC XXE1C0,X       STA $25;********************************; ANIMATE LANDER SPRITES; ON INSTRUCTION SCREEN; AND MAYBE GAME PLAY;********************************	          JMP XXE3A1;********************************;;********************************ZZE1BB .BYTE $38       .BYTE $E8XXE1BD .BYTE $48       .BYTE $00       .BYTE $00XXE1C0 .BYTE $01       .BYTE $E2       .BYTE $42       .BYTE $E2;********************************XXE1C4 LDA $0E       CMP #$14   ;VERTICAL VELOCITY       LDA $0F       SBC #$01       BCC XXE1DB       LDA $09       CMP #$40      ;'@'       LDA $0A       SBC #$01       BCS XXE1DB       LDY #$01       RTS ;********************************XXE1DB LDA $09       CMP #$10       LDA $0A       SBC #$01       BCC XXE1FC       LDA $09       CMP #$D8       LDA $0A       SBC #$01       BCS XXE1FC       LDA $0E       CMP #$74       LDA $0F       SBC #$00       BCC XXE1FC       LDY #$02       RTS ;********************************XXE1FC LDA $09       CMP #$40      ;'@'       LDA $0A       SBC #$01       BCC XXE213       LDA $0E       CMP #$14  ;VERTICAL VELOCITY       LDA $0F       SBC #$01       BCC XXE213       LDY #$03       RTS ;********************************XXE213 LDY #$00       RTS ;********************************; XXE216 TUNE 1 START OF PLAY;********************************XXE216; SID DATA FOR TUNE 1 START OF PLAY.LIB sidmus1.asm;********************************; PLAY TUNE 1 START OF PLAY   ;********************************XXE29A LDA $20       BEQ XXE2C7       LDA #$41      ;'A'       STA VCREG1       LDY #$00XXE2A5 LDX XXE216,Y       INY        LDA XXE216,Y       STA SIDREG       INY        LDA XXE216,Y       STA FREHI1       JSR DELAY1       INY        CPY #$84       BNE XXE2A5       LDA #$00       STA $20       LDA #$40      ;'@'       STA VCREG1XXE2C7 RTS ;********************************;;********************************XXE2C8 JSR XXEB6F ;CHECK FOR KEY OR STICKXXE2CB LDA $13    ;FUEL QTY       BNE XXE2D3       STA $17       STA $16XXE2D3 LDY #$80      ;#$80 1000 0000 NOISE RELEASE       LDA $17       BEQ XXE2FE       LDY #$81       CMP #$02       LDA #$06       LDX #$00       BCC XXE2E7       LDA #$FA       LDX #$FFXXE2E7 CLC        ADC $0B       STA $0B       TXA        ADC $0C       STA $0C       LDA $12       SEC        SBC #$1E       STA $12       LDA $13 ;FUEL QTY       SBC #$00       STA $13 ;FUEL QTYXXE2FE STY $D40B ;VCREG2       LDA $0B       CLC        ADC $08       STA $08       LDA $0C       ADC $09       STA $09       PHP        LDA $0C       ASL A       LDA #$FF       BCS XXE318       LDA #$00XXE318 PLP        ADC $0A       STA $0A       LDA $16       BNE XXE328;	          LDA #$80    ;#$80 1000 0000 NOISE RELEASE       STA VCREG3;	          BNE XXE363XXE328 LDA #$0C       PHA        ASL A       ASL A       ASL A       ADC #$0F       STA $27       LDA $12       SEC        SBC $27       STA $12       LDA $13 ;FUEL QTY       SBC #$00       STA $13 ;FUEL QTY       PLA        STA $27       LDA $10       SEC        SBC $27       STA $10       LDA $11       SBC #$00       STA $11;	          LDA #$E6       STA SUREL3;	          LDA #$28      ;'('       STA CUTHI;	          LDA #$00       STA RESON;	          LDA #$81      ;#$81 VALUE FOR VCREG3	                 ;1000 0001 NOISE ATTACK       JSR XXF254    ;SET SOUND FOR MAIN ENGINE (F1);	   XXE363 LDA $10       CLC        ADC $14       ;VERTICAL VELOCITY       STA $10       LDA $11       ADC #$00       STA $11       LDA $10       CLC        ADC $0D       STA $0D       LDA $11       ADC $0E       STA $0E       PHP        LDA $11       ASL A       LDA #$FF       BCS XXE387       LDA #$00XXE387 PLP        ADC $0F       STA $0F       RTS ;********************************;;********************************XXE38D LDA #$00       STA $1E; DISABLE ALL SRPITES	          LDA #$00       STA SPENA;	          LDA #$00       STA XXPAND       STA YXPAND;	   ; SET LANDER SPRITES FOR GAME PLAY	  ;        JMP XXE3F9;********************************; ANIMATE LANDER SPRITES; ON INSTRUCTION SCREEN;********************************XXE3A1 LDA #$00       STA $1E; DISABLE ALL SRPITES	          LDA #$00       STA SPENA; EXPAND SPRITES 0,1,2,3 (1,2,3)          LDA #$0E    ;0000 1110       STA XXPAND       STA YXPAND;	          JSR XXE3F9       LDX #$02XXE3B7 LDA $0E       CMP XXE3E7,X       BNE XXE3E3       LDA $0F       CMP XXE3EA,X       BNE XXE3E3       LDA $09       CMP XXE3ED,X       LDA $0A       SBC XXE3F0,X       BCC XXE3E3       LDA $09       CMP XXE3F3,X       LDA $0A       SBC XXE3F6,X       BCS XXE3E3       LDA #$01       STA $1E       BNE XXE3E6XXE3E3 DEX        BPL XXE3B7XXE3E6 RTS ;********************************;;********************************XXE3E7 .BYTE $6A       .BYTE $9A       .BYTE $7A;	   XXE3EA .BYTE $01       .BYTE $00       .BYTE $01;XXE3ED .BYTE $B0       .BYTE $60       .BYTE $E0;XXE3F0 .BYTE $00       .BYTE $01       .BYTE $01;XXE3F3 .BYTE $E0       .BYTE $90       .BYTE $00;XXE3F6 .BYTE $00       .BYTE $01       .BYTE $02;********************************; SET LANDER SPRITES FOR INSTRUCTION; SCREEN AND POSSIBLY GAME PLAY;********************************XXE3F9 LDA $2B       EOR #$01       STA $2B;; SET SPRITE 1,2,3 POSITIONS;       LDA SPX       STA SP1X       STA SP2X       STA SP3X;; SET SPRITE 1,2,3 POSITIONS;       LDA $25       STA SP1Y       STA SP2Y       STA SP3Y;          LDX #$00       LDA $24       BEQ XXE41C       DEX XXE41C STX $D010   ;MSIGX       JSR XXEE90  ;CHECK FUEL STATUS       LDX #$01 